// Package topology reads the generated system topology record
// (.intropy/topology.json) that an integration system's AppHost project
// emits. The record declares the system's entities using the Backstage
// catalog taxonomy — Components (blocks), Resources (topics, pub/sub
// brokers, connectors) and APIs (contract surfaces) — plus explicit
// directed edges, an Intropy extension: Backstage core relations are
// dependency-shaped and cannot express which way data flows.
//
// The CLI only consumes this file; it never writes one. Consumers fall
// back to their own heuristics when a system has no topology record.
package topology

import (
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
)

const (
	// SchemaVersion is the newest topology.json schema this CLI
	// understands. Bump only for incompatible changes; additive fields do
	// not require a bump.
	SchemaVersion = 1

	// RelPath is where the topology record lives inside a system root,
	// sibling to the per-project scaffold record convention.
	RelPath = ".intropy/topology.json"
)

// Topology is one system's declared graph. Entity references in edges use
// the form "<kind>:<name>" for entities declared in this file (component:,
// resource:, api:) and full Backstage refs "<kind>:<namespace>/<name>" for
// catalog entities outside it (e.g. "system:default/pim").
type Topology struct {
	SchemaVersion int         `json:"schemaVersion"`
	Generator     Generator   `json:"generator"`
	System        System      `json:"system"`
	Components    []Component `json:"components,omitempty"`
	Resources     []Resource  `json:"resources,omitempty"`
	APIs          []API       `json:"apis,omitempty"`
	Edges         []Edge      `json:"edges,omitempty"`
}

// Generator records what produced the file, so a stale record can be
// traced back to the commit it was generated from.
type Generator struct {
	Tool    string `json:"tool"`
	Version string `json:"version,omitempty"`
	Source  string `json:"source,omitempty"` // e.g. "integrations@3f9c2e1"
}

// System scopes the file. Owner is a Backstage Group ref
// (e.g. "group:default/team-integration").
type System struct {
	Name   string `json:"name"`
	Owner  string `json:"owner,omitempty"`
	Domain string `json:"domain,omitempty"`
}

// Component is a Backstage Component: a deployable block of the system.
// Type is the block type (extractor, assembler, loader, …) or "mock" for
// local stand-ins of external systems.
type Component struct {
	Name string `json:"name"`
	Type string `json:"type"`
	// Tags carry integration identifiers ("int-042"), matching the
	// Backstage catalog tags used for trace lookups.
	Tags []string `json:"tags,omitempty"`
	// Project is the component's directory relative to the system root,
	// joining the node to its .intropy/scaffold.json project.
	Project string `json:"project,omitempty"`
	// Workload is a deployment hint (cronjob, deployment). Recorded but
	// not interpreted by the CLI — deployment is out of scope.
	Workload string `json:"workload,omitempty"`
	// Trigger is declared only when not derivable from edges: a consume
	// edge already implies a topic trigger, a schedule does not.
	Trigger    *Trigger `json:"trigger,omitempty"`
	Image      string   `json:"image,omitempty"`
	Lifecycle  string   `json:"lifecycle,omitempty"` // e.g. "local" for dev-only mocks
	Implements string   `json:"implements,omitempty"`
	Profiles   []string `json:"profiles,omitempty"`
}

// Trigger is a component's non-derivable activation.
type Trigger struct {
	Kind     string `json:"kind"`               // "schedule"
	Schedule string `json:"schedule,omitempty"` // cron expression when Kind is "schedule"
}

// Resource is a Backstage Resource: infrastructure the components use.
// Type decides which optional fields apply: "topic" (PubSub, Entity),
// "pubsub" (none), "connector" (Transport, DaprComponent, ExternalSystem).
type Resource struct {
	Name string `json:"name"`
	Type string `json:"type"`
	// Topic fields.
	PubSub string `json:"pubsub,omitempty"`
	Entity string `json:"entity,omitempty"` // data entity on the topic, e.g. "RawProduct"
	// Connector fields. DaprComponent is the Dapr component's
	// metadata.name, joinable against the project's component YAML.
	Transport      string `json:"transport,omitempty"`
	DaprComponent  string `json:"daprComponent,omitempty"`
	ExternalSystem string `json:"externalSystem,omitempty"` // catalog ref, e.g. "system:default/pim"
}

// API is a Backstage API entity: a contract surface of the system. Topics
// without one are internal; visibility is derived, never declared.
type API struct {
	Name string `json:"name"`
	Type string `json:"type"` // e.g. "asyncapi"
	// Direction is "provides" when this system exports the contract and
	// "consumes" when it imports one another system provides.
	Direction string `json:"direction"`
	Contract  string `json:"contract,omitempty"` // e.g. "Integrio.Contracts.Products"
	Topic     string `json:"topic,omitempty"`    // ref to the topic resource carrying it
}

// Edge is a directed relation between entity refs. Kind is "publish"
// (component → topic), "consume" (topic → component), "connector"
// (connector ↔ component; ordering encodes direction) or "uses"
// (component → catalog entity).
type Edge struct {
	From string `json:"from"`
	To   string `json:"to"`
	Kind string `json:"kind"`
	// Port names the component output a publish edge leaves through.
	Port string `json:"port,omitempty"`
}

// Load reads and parses a topology.json file. A record with a schema
// version this CLI does not understand is an error, not a guess.
func Load(path string) (*Topology, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read topology record %s: %w", path, err)
	}
	var t Topology
	if err := json.Unmarshal(data, &t); err != nil {
		return nil, fmt.Errorf("parse topology record %s: %w", path, err)
	}
	if t.SchemaVersion != SchemaVersion {
		return nil, fmt.Errorf("topology record %s: unsupported schema version %d (this CLI understands %d)",
			path, t.SchemaVersion, SchemaVersion)
	}
	return &t, nil
}

// listSkipDirs mirrors the scaffold walk: directory names never worth
// descending into when scanning for system roots.
var listSkipDirs = map[string]bool{
	".git":         true,
	".intropy":     true,
	"node_modules": true,
	"bin":          true,
	"dist":         true,
}

// Entry is one system found by List: the directory holding the record plus
// the record itself, flattened into one self-describing JSON document.
type Entry struct {
	Path string `json:"path"`
	Topology
}

// List walks the tree rooted at root and returns an entry for every
// directory that contains .intropy/topology.json, in lexical walk order.
// A matched directory is not descended into — systems do not nest.
// Unreadable directories and malformed records become warnings rather than
// failures so one bad record cannot hide the rest.
func List(root string) (entries []Entry, warnings []error) {
	walkErr := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			warnings = append(warnings, err)
			return nil
		}
		if !d.IsDir() {
			return nil
		}
		if path != root && listSkipDirs[d.Name()] {
			return fs.SkipDir
		}

		record := filepath.Join(path, filepath.FromSlash(RelPath))
		if _, err := os.Stat(record); err != nil {
			if !os.IsNotExist(err) {
				warnings = append(warnings, fmt.Errorf("stat %s: %w", record, err))
			}
			return nil
		}
		t, err := Load(record)
		if err != nil {
			// Still a system root — don't descend looking for more.
			warnings = append(warnings, err)
			return fs.SkipDir
		}
		entries = append(entries, Entry{Path: path, Topology: *t})
		return fs.SkipDir
	})
	if walkErr != nil {
		warnings = append(warnings, walkErr)
	}
	return entries, warnings
}

