        var builder = topology.AddComponent("erp-loader", ComponentType.Loader);

        Assert.Same(builder.Component, Assert.Single(topology.Components));
        Assert.Equal("erp-loader", builder.Component.Name);
        Assert.Equal(ComponentType.Loader, builder.Component.Type);
    }

    [Fact]
    public void ProducesTo_adds_a_publish_edge_from_component_to_topic()
    {
        var topology = new SystemTopology("sales");
        var topic = topology.AddTopic("product-raw");

        topology.AddComponent("pim-extractor", ComponentType.Extractor).ProducesTo(topic);

        var edge = Assert.Single(topology.Edges);
        Assert.Equal("component:pim-extractor", edge.From);
        Assert.Equal("resource:product-raw", edge.To);
        Assert.Equal(EdgeKind.Publish, edge.Kind);
    }

    [Fact]
    public void ConsumesFrom_adds_a_consume_edge_from_topic_to_component()
    {
        var topology = new SystemTopology("sales");
        var topic = topology.AddTopic("product-raw");

        topology.AddComponent("erp-loader", ComponentType.Loader).ConsumesFrom(topic);

        var edge = Assert.Single(topology.Edges);
        Assert.Equal("resource:product-raw", edge.From);
        Assert.Equal("component:erp-loader", edge.To);
        Assert.Equal(EdgeKind.Consume, edge.Kind);
    }

    [Fact]
    public void OnSchedule_sets_a_schedule_trigger()
    {
        var topology = new SystemTopology("sales");

        var builder = topology.AddComponent("pim-extractor", ComponentType.Extractor)
            .OnSchedule("*/15 * * * *");

        Assert.NotNull(builder.Component.Trigger);
        Assert.Equal(TriggerKind.Schedule, builder.Component.Trigger!.Kind);
        Assert.Equal("*/15 * * * *", builder.Component.Trigger.Schedule);
    }

