    public void Builder_methods_chain_and_apply_metadata()
    {
        var topology = new SystemTopology("sales");

        var component = topology
            .AddComponent("pim-extractor", ComponentType.Extractor)
            .WithTags("int-042", "products")
            .InProject("pim-extractor")
            .Workload("cronjob")
            .Component;

        Assert.Equal(["int-042", "products"], component.Tags);
        Assert.Equal("pim-extractor", component.Project);
        Assert.Equal("cronjob", component.Workload);
    }
}

