using System.Text.Json.Nodes;
using Intropy.Topology.Models;

namespace Intropy.Topology.Tests;

public class SerializationTests
{
    [Fact]
    public void SchemaVersion_is_always_one()
    {
        var json = JsonNode.Parse(new SystemTopology("sales").ToJson())!;

        Assert.Equal(1, (int)json["schemaVersion"]!);
    }

    [Fact]
    public void Empty_collections_are_omitted()
    {
        var json = JsonNode.Parse(new SystemTopology("sales").ToJson())!.AsObject();

        Assert.False(json.ContainsKey("components"));
        Assert.False(json.ContainsKey("resources"));
        Assert.False(json.ContainsKey("edges"));
    }

    [Fact]
    public void Unset_optional_fields_are_omitted()
    {
        var topology = new SystemTopology("sales");
        topology.AddComponent("erp-loader", ComponentType.Loader);

        var component = JsonNode.Parse(topology.ToJson())!["components"]!.AsArray()[0]!.AsObject();

        Assert.False(component.ContainsKey("project"));
        Assert.False(component.ContainsKey("workload"));
        Assert.False(component.ContainsKey("trigger"));
        Assert.False(component.ContainsKey("tags"));
    }

    [Fact]
    public void Owner_and_domain_are_omitted_when_unset()
    {
        var json = JsonNode.Parse(new SystemTopology("sales").ToJson())!.AsObject();

        Assert.False(json.ContainsKey("owner"));
        Assert.False(json.ContainsKey("domain"));
    }

    [Fact]
    public void Topic_resource_uses_the_pubsub_key()
    {
        var topology = new SystemTopology("sales");
        topology.AddTopic("orders", entity: "Order", pubsub: "pubsub");

        var resource = JsonNode.Parse(topology.ToJson())!["resources"]!.AsArray()[0]!.AsObject();

        Assert.Equal("pubsub", (string?)resource["pubsub"]);
        Assert.Equal("Order", (string?)resource["entity"]);
    }

    [Fact]
    public void Save_writes_the_json_to_disk()
    {
        var path = Path.Combine(Path.GetTempPath(), $"topology-{Guid.NewGuid():N}.json");
        try
        {
            var topology = new SystemTopology("sales");
            topology.Save(path);

            Assert.True(JsonNode.DeepEquals(
                JsonNode.Parse(File.ReadAllText(path)),
                JsonNode.Parse(topology.ToJson())));
        }
        finally
        {
            File.Delete(path);
        }
    }
}

