namespace Intropy.Topology.Models;

/// <summary>
/// A deployable block of the system. Prefer building components through
/// <see cref="SystemTopology.AddComponent"/> and the returned builder rather
/// than wiring edges by hand.
/// </summary>
public sealed class Component
{
    /// <summary>The component's unique name within the system.</summary>
    public required string Name { get; set; }

    /// <summary>The block type.</summary>
    public required ComponentType Type { get; set; }

    /// <summary>Integration identifiers, e.g. "int-042" — the Backstage catalog tags.</summary>
    public List<string> Tags { get; } = [];

    /// <summary>The component's directory relative to the system root.</summary>
    public string? Project { get; set; }

    /// <summary>Deployment hint, e.g. "cronjob" or "deployment". Recorded, not interpreted.</summary>
    public string? Workload { get; set; }

    /// <summary>Non-derivable activation; null when a consume edge already implies the trigger.</summary>
    public Trigger? Trigger { get; set; }
}

